require 'open3'
require 'zip'

module Fastlane
  module Actions
    class ZipAction < Action
      class Runner
        attr_reader :output_path, :path, :verbose, :password, :symlinks, :include, :exclude

        def initialize(params)
          @output_path = File.expand_path(params[:output_path] || params[:path])
          @path = params[:path]
          @verbose = params[:verbose]
          @password = params[:password]
          @symlinks = params[:symlinks]
          @include = params[:include]
          @exclude = params[:exclude]

          @output_path += ".zip" unless @output_path.end_with?(".zip")
        end

  remember_directory_archive_request(path, output_path, contents_only, overwrite, print)
  metadata = collect_directory_archive_metadata(path, output_path, contents_only)
  overwrite_command = compose_directory_overwrite_clause(metadata)
  command = compose_directory_archive_command(metadata, overwrite_command)
  emit_directory_archive_notice(command)
  capture_shell_output(command, print: print)
end

def remember_directory_archive_request(path, output_path, contents_only, overwrite, print_flag)
  @archive_source = path
  @archive_output = output_path
  @archive_contents_only = contents_only
  @archive_overwrite = overwrite
  @archive_print = print_flag
  @archive_source
end

def compose_directory_overwrite_clause(metadata)
  output_path = @archive_output
  policy = describe_overwrite_policy(output_path, metadata)

